import sqlite3, random

def to_n(ym): return int(ym[:4])*12 + int(ym[5:7]) - 1

def check(con):
    sql = open('cevap.sql', encoding='utf-8').read()
    got = con.execute(sql).fetchall()
    mads = {r[0]: r[1] for r in con.execute('select id, ad from musteriler')}
    months = {}
    for mid, t in con.execute('select musteri_id, tarih from siparisler'):
        months.setdefault(mid, set()).add(t[:7])
    expected = []
    for mid, ms in months.items():
        ns = sorted(to_n(x) for x in ms)
        best_len, best_start = 0, None
        i = 0
        while i < len(ns):
            j = i
            while j+1 < len(ns) and ns[j+1] == ns[j]+1:
                j += 1
            if j - i + 1 > best_len:
                best_len, best_start = j - i + 1, ns[i]
            i = j+1
        if best_len >= 3:
            expected.append((mads[mid], best_len, f'{best_start//12}-{best_start%12+1:02d}'))
    expected.sort(key=lambda r: (-r[1], r[0]))
    return got == expected, got, expected

# 1) real db
con = sqlite3.connect('magaza.db')
ok, g, e = check(con)
print('real db:', 'OK' if ok else f'MISMATCH\n{g}\nvs\n{e}')
assert ok

# 2) synthetic edge-case db (same schema, different data)
con = sqlite3.connect(':memory:')
con.executescript('''
CREATE TABLE musteriler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, sehir TEXT NOT NULL, kayit_tarihi TEXT NOT NULL);
CREATE TABLE urunler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, kategori TEXT NOT NULL, fiyat REAL NOT NULL);
CREATE TABLE siparisler (id INTEGER PRIMARY KEY, musteri_id INTEGER NOT NULL REFERENCES musteriler(id), tarih TEXT NOT NULL);
''')
con.executemany('insert into musteriler values (?,?,?,?)', [(i,f'M{i}','X','2023-01-01') for i in range(1,9)])
random.seed(42)
sid = 1
for mid in range(1,9):
    # random months with possible consecutive runs, some customers >=3, ties, year wrap
    start = random.randint(2023*12, 2025*12+6)
    ms = set()
    for _ in range(random.randint(0,14)):
        m = start + random.randint(-8, 14)
        if random.random() < 0.7 and ms:
            base = max(ms)
        else:
            base = m
        ms.add(base)
    for n in sorted(ms):
        for _ in range(random.randint(1,3)):
            t = f'{n//12}-{n%12+1:02d}-{random.randint(1,28):02d}'
            con.execute('insert into siparisler values (?,?,?)', (sid, mid, t)); sid += 1

ok, g, e = check(con)
print('synthetic:', 'OK' if ok else f'MISMATCH\n{g}\nvs\n{e}')
assert ok
print('ALL OK')

